{"type":"span","items":[{"name":"routes/tag.$t","trace":"251b12f4154548b799d383513a59a3c7"},{"name":"GET /tag/:t","trace":"251b12f4154548b799d383513a59a3c7","attrs":{"url.full":".../tag/alpha"}}]}
